app = FastAPI()

v1_router = APIRouter(
    prefix="/api/v1",
    tags=["API V1"]
)

v2_router = APIRouter(
    prefix="/api/v2",
    tags=["API V2"]
)

@v1_router.get("/users")
def get_users_v1():
    return {
        "version": "v1",
        "users": ["Amit", "Riya"]
    }

@v2_router.get("/users")
def get_users_v2():
    return {
        "version": "v2",
        "users": [
            {"id": 1, "name": "Amit"},
            {"id": 2, "name": "Riya"}
        ]
    }

app.include_router(v1_router)
app.include_router(v2_router)
```

The resulting endpoints are:

```text
GET /api/v1/users
GET /api/v2/users
```

